package cn.nebulaedata.cccs.nebuwork.backend.api.preview;

import cn.nebulaedata.cccs.nebuwork.backend.api.agent.*;
import cn.nebulaedata.cccs.nebuwork.backend.api.common.ApiException;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.springframework.core.env.Environment;
import org.springframework.stereotype.Service;
import org.springframework.scheduling.annotation.Scheduled;
import javax.servlet.http.*;
import org.springframework.web.util.ContentCachingResponseWrapper;
import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.sql.*;
import java.util.*;
import static cn.nebulaedata.cccs.nebuwork.backend.api.common.BusinessValues.hash;

@Service public class FilePreviews {
    private static final String RENDERER="office-pdf-table-v1";
    private final AgentStore db;private final AgentClient engine;private final PreviewSources sources;private final ObjectMapper json;private final Environment env;
    public FilePreviews(AgentStore db,AgentClient engine,PreviewSources sources,ObjectMapper json,Environment env){this.db=db;this.engine=engine;this.sources=sources;this.json=json;this.env=env;}
    private long now(){return System.currentTimeMillis();}
    private long ttl(){return env.getProperty("nebu.files.preview-ttl-ms",Long.class,7L*86400000);}
    public void enabled(){if(!env.getProperty("nebu.files.enabled",Boolean.class,false))throw new ApiException(503,"大文件预览尚未启用");}
    private JsonNode read(Object v){try{return v==null?json.createObjectNode():json.readTree(v.toString());}catch(Exception e){throw new ApiException(500,"预览记录无效");}}
    private Map<String,Object> row(String id){Map<String,Object> r=db.one("SELECT * FROM nw_file_preview WHERE id=?",id);if(r==null)throw new ApiException(404,"预览不存在");return r;}
    private Map<String,Object> owned(String owner,String id){enabled();Map<String,Object> r=row(id);if(!owner.equals(r.get("owner_id")))throw new ApiException(404,"预览不存在");sources.metadata(owner,read(r.get("source_json")));return r;}
    private String extension(JsonNode m){String name=m.path("name").asText();int dot=name.lastIndexOf('.');String ext=dot>=0?name.substring(dot+1).toLowerCase(Locale.ROOT):m.path("fileType").asText().toLowerCase(Locale.ROOT);String mime=m.path("mediaType").asText().toLowerCase(Locale.ROOT);if(mime.equals("application/pdf"))return "pdf";if(mime.equals("application/vnd.openxmlformats-officedocument.wordprocessingml.document"))return "docx";if(mime.equals("application/vnd.openxmlformats-officedocument.presentationml.presentation"))return "pptx";if(mime.equals("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"))return "xlsx";return ext;}
    private boolean nativeFile(JsonNode m){return Arrays.asList("pdf","png","jpg","jpeg","gif","webp","bmp","svg","avif","mp3","wav","m4a","ogg","aac","flac","mp4","webm","mov","m4v","opus").contains(extension(m));}
    public Object create(String owner,JsonNode body){
        enabled();body.fieldNames().forEachRemaining(k->{if(!Arrays.asList("source","indexText","downloadOnly").contains(k))throw new ApiException(422,"未知预览参数");});ObjectNode source=sources.validate(body.path("source"));JsonNode metadata=sources.metadata(owner,source);
        String sourceHash=metadata.path("sha256").asText(metadata.path("sourceHash").asText());if(!sourceHash.isEmpty())source.put("expectedHash",sourceHash);
        boolean index=body.path("indexText").asBoolean();if(index&&!"pdf".equals(extension(metadata)))index=false;
        boolean downloadOnly=body.path("downloadOnly").asBoolean();String ext=extension(metadata);if(!downloadOnly&&!nativeFile(metadata)&&!Arrays.asList("docx","pptx","xlsx","xls","csv","tsv","tab").contains(ext))throw new ApiException(422,"此格式不支持后台预览");
        if(!source.hasNonNull("expectedHash")&& !"artifact".equals(source.path("kind").asText()))throw new ApiException(422,"此知识库版本缺少文件指纹，无法建立固定版本大文件预览");
        String key=hash(owner+":"+source.toString()+":"+metadata.path("version")+":"+RENDERER+":"+index+":"+downloadOnly),id="fp-"+key.substring(0,48);long time=now();String status=downloadOnly||nativeFile(metadata)&&!index?"ready":"queued";
        ObjectNode stored=json.createObjectNode();for(String field:Arrays.asList("name","size","fileType","mediaType","version","sha256","sourceHash"))if(metadata.has(field))stored.set(field,metadata.get(field));stored.put("fileType",ext);stored.put("indexText",index);stored.put("downloadOnly",downloadOnly);
        ObjectNode manifest=json.createObjectNode();manifest.put("kind",downloadOnly?"download-only":status.equals("ready")?"native":"");
        db.update("INSERT INTO nw_file_preview(id,owner_id,cache_key,source_json,metadata_json,status,manifest_json,created_at,expires_at) VALUES(?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE id=id",id,owner,key,source.toString(),stored.toString(),status,manifest.toString(),time,time+ttl());return status(owner,id);
    }
    public Object status(String owner,String id){Map<String,Object> r=owned(owner,id);Map<String,Object> result=new LinkedHashMap<>();result.put("id",id);result.put("status",((Number)r.get("expires_at")).longValue()<now()?"expired":r.get("status"));result.put("stage",r.get("stage"));result.put("error",r.get("error_text"));result.put("metadata",read(r.get("metadata_json")));result.put("manifest",read(r.get("manifest_json")));result.put("expiresAt",r.get("expires_at"));return result;}
    public Object action(String owner,String id,String action){Map<String,Object> r=owned(owner,id);String state=r.get("status").toString();
        if("cancel".equals(action)){db.update("UPDATE nw_file_preview SET status='cancelled',lease_token=NULL,active_owner=NULL,lease_until=0 WHERE id=? AND status IN ('queued','reading','converting')",id);}
        else if(Arrays.asList("failed","cancelled","expired").contains(state)||((Number)r.get("expires_at")).longValue()<now())db.update("UPDATE nw_file_preview SET status=?,error_text=NULL,lease_token=NULL,active_owner=NULL,lease_until=0,expires_at=? WHERE id=?",read(r.get("metadata_json")).path("downloadOnly").asBoolean()||nativeFile(read(r.get("metadata_json")))&&!read(r.get("metadata_json")).path("indexText").asBoolean()?"ready":"queued",now()+ttl(),id);
        return status(owner,id);
    }
    public void content(String owner,String id,String range,HttpServletResponse response)throws IOException{Map<String,Object> r=owned(owner,id);ready(r);JsonNode manifest=read(r.get("manifest_json"));if("native".equals(manifest.path("kind").asText())){if("svg".equals(extension(read(r.get("metadata_json")))))response.setHeader("Content-Security-Policy","sandbox; default-src 'none'; style-src 'unsafe-inline'");sources.stream(owner,read(r.get("source_json")),range,"pdf".equals(extension(read(r.get("metadata_json"))))?new HttpServletResponseWrapper(response){@Override public void setHeader(String k,String v){super.setHeader(k,"Content-Type".equalsIgnoreCase(k)?"application/pdf":v);}}:response);}else if("pdf".equals(manifest.path("kind").asText()))output(owner,id,"document.pdf",range,response);else if("indexed-pdf".equals(manifest.path("kind").asText()))sources.stream(owner,read(r.get("source_json")),range,"pdf".equals(extension(read(r.get("metadata_json"))))?new HttpServletResponseWrapper(response){@Override public void setHeader(String k,String v){super.setHeader(k,"Content-Type".equalsIgnoreCase(k)?"application/pdf":v);}}:response);else throw new ApiException(422,"此预览使用表格分页读取");}
    private void ready(Map<String,Object> r){if(((Number)r.get("expires_at")).longValue()<now())throw new ApiException(410,"预览已过期");if(!"ready".equals(r.get("status")))throw new ApiException(409,"预览尚未完成");}
    public void download(String owner,String id,HttpServletResponse response)throws IOException{Map<String,Object> r=owned(owner,id);String name=read(r.get("metadata_json")).path("name").asText("document");response.setHeader("Content-Disposition","attachment; filename*=UTF-8''"+java.net.URLEncoder.encode(name,"UTF-8").replace("+","%20"));sources.stream(owner,read(r.get("source_json")),null,new HttpServletResponseWrapper(response){@Override public void setHeader(String key,String value){if(!key.equalsIgnoreCase("Content-Disposition"))super.setHeader(key,value);}});}
    public Object cell(String owner,String id,String sheet,long row,int column,int start,HttpServletResponse response)throws Exception{Map<String,Object> r=owned(owner,id);ready(r);if(row<0||column<0||start<0)throw new ApiException(422,"单元格范围无效");Path file=indexFile(owner,id,"table.sqlite",response);try(Connection c=DriverManager.getConnection("jdbc:sqlite:file:"+file.toAbsolutePath().toString().replace('\\','/')+"?mode=ro&immutable=1");PreparedStatement q=c.prepareStatement("SELECT substr(value,?,16384),length(value) FROM cells WHERE sheet=? AND r=? AND c=?")){q.setLong(1,(long)start+1);q.setString(2,sheet);q.setLong(3,row);q.setInt(4,column);try(ResultSet rs=q.executeQuery()){if(!rs.next())throw new ApiException(404,"单元格不存在");Map<String,Object> result=new LinkedHashMap<>();result.put("text",rs.getString(1));result.put("length",rs.getLong(2));result.put("start",start);return result;}}}
    private void output(String owner,String id,String name,String range,HttpServletResponse response)throws IOException{Map<String,Object> out=db.one("SELECT * FROM nw_file_preview_output WHERE preview_id=? AND owner_id=? AND output_name=?",id,owner,name);if(out==null)throw new ApiException(404,"预览文件不存在");engine.fileStream(owner,null,"/v1/preview-objects/"+AgentClient.segment(out.get("upload_id").toString()),range,response);}
    private final Object cacheGuard=new Object();
    private long cacheSize(Path root)throws IOException{long bytes=0;try(DirectoryStream<Path> files=Files.newDirectoryStream(root,"*.sqlite")){for(Path file:files)bytes+=Files.size(file);}return bytes;}
    private void cleanCache(Path root)throws IOException{
        long cutoff=now()-ttl(),quota=env.getProperty("nebu.files.preview-cache-bytes",Long.class,128L*1024*1024*1024);List<Path> keep=new ArrayList<>();
        try(DirectoryStream<Path> files=Files.newDirectoryStream(root,"*.sqlite")){for(Path file:files){if(Files.getLastModifiedTime(file).toMillis()<cutoff)Files.deleteIfExists(file);else keep.add(file);}}
        keep.sort(Comparator.comparingLong(p->{try{return Files.getLastModifiedTime(p).toMillis();}catch(IOException e){return 0;}}));long used=cacheSize(root);
        for(Path file:keep){if(used<=Math.max(0,quota-64L*1024*1024*1024))break;long size=Files.size(file);Files.deleteIfExists(file);used-=size;}
        try(DirectoryStream<Path> files=Files.newDirectoryStream(root,"download-*.tmp")){for(Path file:files)if(Files.getLastModifiedTime(file).toMillis()<now()-3600000L)Files.deleteIfExists(file);}
    }
    private Path indexFile(String owner,String id,String name,HttpServletResponse response)throws IOException{
        Path root=Paths.get(env.getProperty("nebu.files.preview-cache-dir",System.getProperty("java.io.tmpdir")+"/nebu-preview-cache"));Files.createDirectories(root);Path target=root.resolve(hash(owner+":"+id+":"+name+":"+String.valueOf(db.one("SELECT upload_id FROM nw_file_preview_output WHERE preview_id=? AND output_name=?",id,name)))+".sqlite");
        synchronized(cacheGuard){if(!Files.exists(target)){cleanCache(root);long existing=cacheSize(root),quota=env.getProperty("nebu.files.preview-cache-bytes",Long.class,128L*1024*1024*1024);Path temp=Files.createTempFile(root,"download-",".tmp");try{try(OutputStream stream=Files.newOutputStream(temp)){
            HttpServletResponse sink=new HttpServletResponseWrapper(response){private int code=200;private final javax.servlet.ServletOutputStream out=new javax.servlet.ServletOutputStream(){long count;public void write(int b)throws IOException{write(new byte[]{(byte)b},0,1);}public void write(byte[] b,int o,int n)throws IOException{count+=n;if(count>64L*1024*1024*1024||count+existing>quota)throw new IOException("index size");stream.write(b,o,n);}public boolean isReady(){return true;}public void setWriteListener(javax.servlet.WriteListener l){}};@Override public javax.servlet.ServletOutputStream getOutputStream(){return out;}@Override public void setStatus(int s){code=s;if(s!=200)throw new ApiException(502,"预览索引读取失败");}@Override public void setHeader(String n,String v){} };
            output(owner,id,name,null,sink);stream.flush();}Files.move(temp,target,StandardCopyOption.ATOMIC_MOVE);
        }finally{Files.deleteIfExists(temp);}}}return target;
    }
    public Object rows(String owner,String id,String sheet,long row,int column,int limit,int columns,HttpServletResponse response)throws Exception{
        Map<String,Object> r=owned(owner,id);ready(r);JsonNode manifest=read(r.get("manifest_json"));if(!"table".equals(manifest.path("kind").asText())||row<0||column<0||limit<1||limit>200||columns<1||columns>50)throw new ApiException(422,"表格分页范围无效");
        JsonNode selected=null;for(JsonNode s:manifest.path("sheets"))if(sheet.equals(s.path("id").asText()))selected=s;if(selected==null)throw new ApiException(404,"工作表不存在");
        List<Object> cells=new ArrayList<>();Path file=indexFile(owner,id,"table.sqlite",response);
        try(Connection c=DriverManager.getConnection("jdbc:sqlite:file:"+file.toAbsolutePath().toString().replace('\\','/')+"?mode=ro&immutable=1");PreparedStatement q=c.prepareStatement("SELECT r,c,substr(value,1,4096),length(value) FROM cells WHERE sheet=? AND r>=? AND r<? AND c>=? AND c<? ORDER BY r,c")){q.setString(1,sheet);q.setLong(2,row);q.setLong(3,(long)row+limit);q.setLong(4,column);q.setLong(5,(long)column+columns);try(ResultSet rs=q.executeQuery()){while(rs.next()){Map<String,Object> cell=new LinkedHashMap<>();cell.put("row",rs.getLong(1));cell.put("column",rs.getInt(2));cell.put("text",rs.getString(3));cell.put("length",rs.getInt(4));cells.add(cell);}}}
        Map<String,Object> result=new LinkedHashMap<>();result.put("sheet",selected);result.put("row",row);result.put("column",column);result.put("cells",cells);return result;
    }
    public Object locate(String owner,String id,JsonNode body,HttpServletResponse response)throws Exception{
        Map<String,Object> r=owned(owner,id);ready(r);String quote=body.path("quote").asText().replaceAll("\\s+"," ").trim();if(quote.isEmpty()||quote.length()>16000)throw new ApiException(422,"引用文本长度无效");Path file=indexFile(owner,id,"index.sqlite",response);List<Integer> hits=new ArrayList<>();String carry="";int previous=0;
        try(Connection c=DriverManager.getConnection("jdbc:sqlite:file:"+file.toAbsolutePath().toString().replace('\\','/')+"?mode=ro&immutable=1");Statement q=c.createStatement();ResultSet rs=q.executeQuery("SELECT page,text FROM page_text ORDER BY page")){while(rs.next()){int page=rs.getInt(1);String text=rs.getString(2).replaceAll("\\s+"," "),joined=carry+text;int at=joined.indexOf(quote);while(at>=0){hits.add(at<carry.length()?previous:page);if(hits.size()>1)break;at=joined.indexOf(quote,at+1);}if(hits.size()>1)break;carry=text.substring(Math.max(0,text.length()-quote.length()+1));previous=page;}}
        Map<String,Object> result=new LinkedHashMap<>();result.put("reason",hits.isEmpty()?"missing":hits.size()>1?"ambiguous":null);result.put("pages",hits.size()==1?hits:Collections.emptyList());return result;
    }
    public void workerAuth(String supplied){enabled();String expected=env.getProperty("nebu.files.worker-key","");if(expected.length()<32||supplied==null||!MessageDigest.isEqual(("Bearer "+expected).getBytes(StandardCharsets.UTF_8),supplied.getBytes(StandardCharsets.UTF_8)))throw new ApiException(401,"预览 Worker 认证失败");}
    public Object claim(){
        long time=now();for(Map<String,Object> r:db.rows("SELECT p.* FROM nw_file_preview p WHERE p.expires_at>? AND (p.status='queued' OR (p.status IN ('reading','converting') AND p.lease_until<?)) AND NOT EXISTS(SELECT 1 FROM nw_file_preview a WHERE a.owner_id=p.owner_id AND a.status IN ('reading','converting') AND a.lease_until>?) ORDER BY p.created_at LIMIT 20",time,time,time)){
            String owner=r.get("owner_id").toString(),id=r.get("id").toString();Map<String,Object> active=db.one("SELECT id FROM nw_file_preview WHERE owner_id=? AND status IN ('reading','converting') AND lease_until>? LIMIT 1",owner,time);if(active!=null)continue;
            String token=UUID.randomUUID().toString();try{if(db.update("UPDATE nw_file_preview SET status='reading',stage='读取原文件',active_owner=owner_id,lease_token=?,lease_until=?,started_at=?,attempt=attempt+1 WHERE id=? AND (status='queued' OR (status IN ('reading','converting') AND lease_until<?))",token,time+120000,time,id,time)==0)continue;}catch(org.springframework.dao.DuplicateKeyException busy){continue;}
            try{sources.metadata(owner,read(r.get("source_json")));Map<String,Object> job=new LinkedHashMap<>();job.put("id",id);job.put("lease",token);job.put("metadata",read(r.get("metadata_json")));job.put("expectedHash",read(r.get("source_json" )).path("expectedHash").asText());return job;}catch(Exception e){db.update("UPDATE nw_file_preview SET status='failed',error_text='来源权限已撤销或文件版本变化',lease_token=NULL,active_owner=NULL WHERE id=? AND lease_token=?",id,token);}
        }return null;
    }
    private Map<String,Object> leased(String id,String token){Map<String,Object> r=row(id);if(token==null||!token.equals(r.get("lease_token"))||!Arrays.asList("reading","converting").contains(r.get("status"))||((Number)r.get("lease_until")).longValue()<now())throw new ApiException(409,"预览任务租约已失效");if(now()-((Number)r.get("started_at")).longValue()>env.getProperty("nebu.files.worker-timeout-ms",Long.class,3600000L))throw new ApiException(409,"预览任务处理超时");sources.metadata(r.get("owner_id").toString(),read(r.get("source_json")));return r;}
    public Object heartbeat(String id,String token,JsonNode body){leased(id,token);String stage=body.path("stage").asText("处理中");if(stage.length()>64)throw new ApiException(422,"处理阶段过长");db.update("UPDATE nw_file_preview SET lease_until=?,status='converting',stage=? WHERE id=? AND lease_token=?",now()+120000,stage,id,token);return Collections.singletonMap("ok",true);}
    public void input(String id,String token,HttpServletResponse response)throws IOException{Map<String,Object> r=leased(id,token);sources.stream(r.get("owner_id").toString(),read(r.get("source_json")),null,response);}
    public Object outputCreate(String id,String token,JsonNode body){Map<String,Object> r=leased(id,token);String name=body.path("name").asText();if(!Arrays.asList("document.pdf","table.sqlite","index.sqlite").contains(name))throw new ApiException(422,"预览输出名称无效");ObjectNode input=json.createObjectNode();input.put("name",name);input.set("size",body.path("size"));input.put("mediaType",name.endsWith(".pdf")?"application/pdf":"application/vnd.sqlite3");input.put("purpose","preview");
        JsonNode upload=engine.post(r.get("owner_id").toString(),null,"/v1/projects/__file_preview__/file-uploads",input,"preview:"+id+":"+r.get("attempt")+":"+name);db.update("INSERT INTO nw_file_preview_output(preview_id,owner_id,output_name,upload_id) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE upload_id=VALUES(upload_id)",id,r.get("owner_id"),name,upload.path("id").asText());return upload;}
    private Map<String,Object> uploadLease(String id,String token,String upload){Map<String,Object> r=leased(id,token);if(db.one("SELECT upload_id FROM nw_file_preview_output WHERE preview_id=? AND upload_id=?",id,upload)==null)throw new ApiException(404,"输出上传不存在");return r;}
    public Object outputStatus(String id,String token,String upload){Map<String,Object> r=uploadLease(id,token,upload);return engine.get(r.get("owner_id").toString(),null,"/v1/file-uploads/"+AgentClient.segment(upload));}
    public Object outputPart(String id,String token,String upload,int number,String digest,InputStream input,long length){Map<String,Object> r=uploadLease(id,token,upload);return engine.filePart(r.get("owner_id").toString(),null,upload,number,digest,input,length);}
    public Object outputComplete(String id,String token,String upload){Map<String,Object> r=uploadLease(id,token,upload);return engine.post(r.get("owner_id").toString(),null,"/v1/file-uploads/"+AgentClient.segment(upload)+"/complete",Collections.emptyMap(),"complete:"+upload);}
    public Object finish(String id,String token,JsonNode body){Map<String,Object> r=leased(id,token);String error=body.path("error").asText();if(!error.isEmpty()){db.update("UPDATE nw_file_preview SET status='failed',error_text=?,lease_token=NULL,active_owner=NULL WHERE id=? AND lease_token=?",error.substring(0,Math.min(500,error.length())),id,token);return Collections.singletonMap("ok",true);}
        String digest=body.path("sourceSha256").asText();if(!digest.matches("[a-f0-9]{64}"))throw new ApiException(422,"原文件校验值无效");String expected=read(r.get("source_json")).path("expectedHash").asText();if(expected.length()==64&&!expected.equals(digest))throw new ApiException(409,"原文件指纹不匹配");JsonNode manifest=body.path("manifest");if(!Arrays.asList("pdf","table","indexed-pdf").contains(manifest.path("kind").asText())||manifest.toString().length()>1048576)throw new ApiException(422,"预览清单无效");
        List<String> required=new ArrayList<>();if("pdf".equals(manifest.path("kind").asText()))required.add("document.pdf");required.add("table".equals(manifest.path("kind").asText())?"table.sqlite":"index.sqlite");for(String name:required){Map<String,Object> output=db.one("SELECT upload_id FROM nw_file_preview_output WHERE preview_id=? AND output_name=?",id,name);if(output==null||!"complete".equals(engine.get(r.get("owner_id").toString(),null,"/v1/file-uploads/"+AgentClient.segment(output.get("upload_id").toString())).path("status").asText()))throw new ApiException(409,"预览输出尚未校验完成");}
        db.update("UPDATE nw_file_preview SET status='ready',stage='完成',manifest_json=?,source_sha256=?,lease_token=NULL,active_owner=NULL,lease_until=0,error_text=NULL WHERE id=? AND lease_token=?",manifest.toString(),digest,id,token);return Collections.singletonMap("ok",true);
    }
    @Scheduled(fixedDelay=60000)public void expire(){if(!env.getProperty("nebu.files.enabled",Boolean.class,false))return;db.update("UPDATE nw_file_preview SET status='expired',lease_token=NULL,active_owner=NULL WHERE expires_at<? AND status<>'expired'",now());db.update("UPDATE nw_file_preview SET status='failed',lease_token=NULL,active_owner=NULL,error_text='处理超时，可重试' WHERE status IN ('reading','converting') AND started_at<?",now()-env.getProperty("nebu.files.worker-timeout-ms",Long.class,3600000L));synchronized(cacheGuard){try{Path root=Paths.get(env.getProperty("nebu.files.preview-cache-dir",System.getProperty("java.io.tmpdir")+"/nebu-preview-cache"));if(Files.isDirectory(root))cleanCache(root);}catch(IOException ignored){}}}
}
